contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 unused) public payable {
        require(address(this).balance >= 1 ether);

        // setup: try to make the contract non-open initially? It starts closed by constructor.
        // We are the owner, so OpenToThePublic should succeed the first time.
        bool revertedFirst;
        try c.OpenToThePublic() { revertedFirst = false; } catch { revertedFirst = true; }

        // To test the non-owner revert, we need a different caller than msg.sender.
        // We cannot change msg.sender for a call on c from this run function.
        // But we can still check the owner case: first call succeeds, and after success the contract is open,
        // so a second call by the owner also succeeds (modifier onlyOwner passes, no check on openToPublic).
        bool revertedSecond;
        try c.OpenToThePublic() { revertedSecond = false; } catch { revertedSecond = true; }

        // Also, when open, donate should succeed for any caller (we are the caller, payer).
        // But note: donate is payable and uses onlyOpenToThePublic. We need to send value.
        uint256 amount = 1;
        bool revertedDonate;
        try c.donate{value: amount}() { revertedDonate = false; } catch { revertedDonate = true; }

        // General rule: after a successful OpenToThePublic call by the owner, the contract becomes open,
        // so a subsequent call to OpenToThePublic by the owner also succeeds, and donate() succeeds.
        // If the contract was already open before the first call, the first call still succeeds (no revert).
        // The only way OpenToThePublic reverts is if the caller is not the owner; but in this test the caller is always the owner.
        // Therefore, for all inputs (unused param), since the test contract is the owner, OpenToThePublic never reverts.
        assert(!revertedFirst && !revertedSecond && !revertedDonate);
    }

    receive() external payable {}
}

